draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // Mother figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // Secure child
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100 + 50*Math.sin(t), H/2 + 100, 15, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 50*Math.sin(t), H/2 + 115);
  ctx.lineTo(W/2 - 100 + 50*Math.sin(t), H/2 + 145);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 50*Math.sin(t), H/2 + 145);
  ctx.lineTo(W/2 - 120 + 50*Math.sin(t), H/2 + 165);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 50*Math.sin(t), H/2 + 145);
  ctx.lineTo(W/2 - 80 + 50*Math.sin(t), H/2 + 165);
  ctx.stroke();

  // Anxious child
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 20*Math.cos(t), H/2 + 100, 15, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 20*Math.cos(t), H/2 + 115);
  ctx.lineTo(W/2 + 100 + 20*Math.cos(t), H/2 + 145);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 20*Math.cos(t), H/2 + 145);
  ctx.lineTo(W/2 + 80 + 20*Math.cos(t), H/2 + 165);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 20*Math.cos(t), H/2 + 145);
  ctx.lineTo(W/2 + 120 + 20*Math.cos(t), H/2 + 165);
  ctx.stroke();

  ctx.restore();
}
